class Solution:
    def threeSumClosest(self, nums: List[int], target: int) -> int:
        nums.sort()
        n = len(nums)
        best = float("inf")

        for i in range(n - 2):
            l, r = i + 1, n - 1
            while l < r:
                total = nums[i] + nums[l] + nums[r]

                if total == target:
                    return total
                elif total < target:
                    l += 1
                else:
                    r -= 1

                if abs(target - total) < abs(target - best):
                    best = total


        return best
